'use strict';
// Curated existing-route SEO discovery, not 44 autogenerated thin URL pages.
function createServiceCenterTaksong({data,vehicleTopicMap,vehicleTopicPath,esc,compact}){
 const targetByKeyword=new Map();
 const ids=new Set();
 for(const group of data.groups||[]){
  if(!/^[-a-z]+$/.test(group.id)||ids.has(group.id)||!group.title||!group.description||!group.action||
     !Array.isArray(group.keywords)||!group.keywords.length||!/^\/(?:service|taksong)\//.test(group.landing))
   throw Error('Invalid service-center guide');
  ids.add(group.id);
  for(const word of group.keywords){
   const key=compact(word).toLowerCase();
   if(!key||targetByKeyword.has(key))throw Error('Duplicate service-center keyword: '+word);
   targetByKeyword.set(key,vehicleTopicMap.has(word)?vehicleTopicPath(word):'/taksong/types/#'+group.id);
  }
 }
 if(ids.size!==3)throw Error('Expected three evidence-reviewed service-center families');
 for(const {input,to} of data.aliases||[]){
  const target=targetByKeyword.get(compact(to).toLowerCase()),key=compact(input).toLowerCase();
  if(!target||!key||targetByKeyword.has(key))throw Error('Invalid service-center search alias: '+input);
  targetByKeyword.set(key,target);
 }
 function find(word){return targetByKeyword.get(compact(word||'').toLowerCase())||null}
 function markup(compactView=false){
  if(compactView)return '<section id="national-service-center-categories"><h2>국산차·수입차·대형트럭 서비스센터 탁송</h2><p>승용차 정비센터와 상용차·대형트럭 정비사업소는 차량 인수 조건이 다릅니다. 벤츠·볼보·현대 승용차 센터와 현대 상용차 전담 블루핸즈, 타타대우모빌리티·볼보트럭·벤츠트럭의 정비 거점을 구분해 입고·출고를 상담합니다. 공식 제휴나 운행 완료를 뜻하지 않습니다.</p><p><a href="/taksong/types/#domestic-service-centers">국산차 서비스센터 탁송</a> · <a href="/taksong/types/#imported-service-centers">수입차 서비스센터 탁송</a> · <a href="/taksong/types/#commercial-truck-service-centers">대형트럭 서비스센터 탁송</a></p></section>';
  const groupHtml=data.groups.map(group=>{
   const terms=group.keywords.map(word=>{
    const href=vehicleTopicMap.has(word)?vehicleTopicPath(word):null;
    return '<li>'+(href?'<a href="'+esc(href)+'">'+esc(word)+'</a>':'<span>'+esc(word)+'</span>')+'</li>';
   }).join('');
   return '<section id="'+group.id+'" aria-label="'+esc(group.title)+'"><h2>'+esc(group.title)+'</h2><p>'+esc(group.description)+'</p><h3>입고·출고 예약 시 확인할 사항</h3><p>'+esc(group.action)+'</p><ul>'+terms+'</ul><p><a href="'+esc(group.landing)+'">차량 이동·기사 자격 상세 안내</a> · <a href="/fare/?service=taksong">예상요금 조회</a> · <a href="tel:18114294">탁송 상담 1811-4294</a></p></section>';
  }).join('');
  const refs=(data.references||[]).map(x=>{
   if(!/^https:\/\//.test(x.url))throw Error('Invalid source protocol');
   return '<li><a href="'+esc(x.url)+'" rel="noopener noreferrer" target="_blank">'+esc(x.label)+'</a></li>';
  }).join('');
  return '<section id="service-center-keywords-20261117"><h2>국산차·수입차·대형트럭 서비스센터 탁송 안내</h2><p>이 키워드는 고객의 차량 이동 목적을 구분하기 위한 안내입니다. 제조사 정비와 차량탁송은 다른 서비스이며 공식 제휴·현장 기사 상주·완료 운행을 뜻하지 않습니다.</p>'+groupHtml+'<section><h3>공식 서비스 네트워크에서 정비 대상 확인</h3><p>정비 가능한 차종과 방문 지점은 각 제조사의 공식 안내에서 확인해야 합니다. 서비스센터 정비예약과 로드탁송 배차는 별도입니다.</p><ul>'+refs+'</ul></section></section>';
 }
 const passengerContext={
  '현대서비스센터탁송':'현대 승용·SUV 정비와 현대 중대형 상용차 정비는 시설과 입고 가능 차종을 구분해야 합니다. 블루핸즈라도 차량별 정비 가능 여부와 예약 시각을 먼저 확인하세요.',
  '벤츠서비스센터탁송':'벤츠 승용차 서비스센터 입출고와 메르세데스-벤츠 대형트럭의 정비·출고는 서로 다른 차량 및 정비 거점 기준으로 상담해야 합니다.',
  '볼보서비스센터탁송':'볼보 승용차 서비스센터와 볼보트럭코리아의 트럭 정비 사업소는 구분해야 합니다. 차량 종류와 정확한 정비사업소·인수 지점을 확인해 주세요.'
 };
 return {find,markup,passengerContext,keywordCount:targetByKeyword.size};
}
module.exports={createServiceCenterTaksong};
